\label{conj:strong-stmod}
If $\hat H^{\geqslant 0}(G,M)$ is finitely generated as a module over $H^*(G,k)$ then
$M$ is cohomologically equivalent to a finitely generated $k G$-module.

\label{conj:strong-Db}
If $X$ is in $\mathsf{KInj}^{\mathsf{b}}(k G)$ then $X$ is cohomologically equivalent to
an object in $\mathsf{D}^{\mathsf{b}}(k G)$.

\label{conj:strong-DC}
If $Y$ is in $\mathsf{D}^{\mathsf{b}}(C^*BG)$ then there is an object $X$ in $\mathsf{D}^{\mathsf{b}}(k G)$
such that $Y$ is equivalent to $C^*(BG;X)$.

\label{conj:weak-DC}
$\mathsf{D}^{\mathsf{b}}(C^*BG)$ is generated as a thick subcategory of $\mathsf{D}(C^*BG)$ by the objects
$C^*(BG;X)$ for $X$ in $\mathsf{D}^{\mathsf{b}}(k G)$.

\label{conj:C*BS}
The bounded derived category $\mathsf{D}^{\mathsf{b}}(C^*BG)$ is generated by the
module $C^*BS$, where $S$ is a Sylow $p$-subgroup of $G$.

\label{le:dual}
Suppose that a $k G$-module $M$ has no projective summands. 
Then neither does the dual $M^\vee=\mathsf{Hom}_k(M,k)$.

\begin{equation}\label{eq:KInjb/KInj0}
\mathsf{KInj}^{\mathsf{b}}(k G)/\mathsf{KInj}^0(k G)\xrightarrow{\sim}\mathsf{Loc}^{\mathsf b}(\mathsf{ik}).
\end{equation}

\label{th:equivalences}
Conjecture~\ref{conj:strong-stmod} is equivalent to
Conjecture~\ref{conj:strong-Db}, and Conjecture~\ref{conj:weak-stmod}
is equivalent to Conjecture~\ref{conj:weak-Db}.

We use a slight variation of the definition of \emph{nucleus} from the
papers of Benson, Carlson and Robinson~\cite{Benson/Carlson/Robinson:1990a} 
and Benson~\cite{Benson:1995a}
to accommodate the fact that we are working with the bounded derived
category $\mathsf{D}^{\mathsf{b}}(k G)$ rather than the stable module category 
$\mathsf{stmod}(k G)$.

\label{th:nucleus}
The category $\mathsf{D}^{\mathsf{b}}(B_0(k G))$ is generated by $k$ and 
finitely generated modules $M$ with $V_G(M)\subseteq \Theta_G$.

\label{co:zero-nucleus}
If $\Theta_G=\varnothing$ or $\Theta_G=\{0\}$ then
Conjectures~\ref{conj:strong-stmod}--\ref{conj:C*BS} hold for $k G$.

\label{pr:Fred}
If $\Omega BG{}^{^\wedge}_p$ has finite dimensional cohomology then its
connected components are contractible.

\label{th:Dsg=0}
The singularity category $\mathsf{D}_{\mathsf{sg}}(C^*BG)$ is zero if and only if $G$ is
$p$-nilpotent.

\label{th:C*BS=>suppDsg}
Conjecture~\ref{conj:C*BS} for a finite group $G$ implies that the support of $\mathsf{D}_{\mathsf{sg}}(C^*BG)$
is contained in $\Theta_G$.
